'SELECT * FROM ', item().source_schema, '.', item().source_table,
' WHERE ', item().watermark_column,
' > ''', variables('watermark'), ''''
)

text.value:
DECLARE @calculated_watermark_to NVARCHAR(50) = 'NULL';

IF @load_type != 'FULL' AND @watermark_column IS NOT NULL
BEGIN
    DECLARE @sql NVARCHAR(MAX);
    DECLARE @param_definition NVARCHAR(500) = N'@res NVARCHAR(50) OUTPUT';

    SET @sql = N'SELECT @res = CAST(MAX([' + REPLACE(@watermark_column, '''', '''''') + ']) AS NVARCHAR(50)) FROM [' + REPLACE(@target_schema, '''', '''''') + '].[' + REPLACE(@target_table, '''', '''''') + ']';

    EXEC sp_executesql @sql, @param_definition, @res = @calculated_watermark_to OUTPUT;
END

-- Gọi Procedure log với các tham số sạch
EXEC meta.usp_etl_log 
    @action = 'entity_success',
    @pipeline_run_id = @pipeline_run_id,
    @pipeline_name = @pipeline_name,
    @controller_id = @controller_id,
    @log_id = @log_id,
    @load_type = @load_type,
    @rows_read = @rows_read,
    @rows_inserted = @rows_read, 
    @watermark_from = @watermark_from,
    @watermark_to = @calculated_watermark_to;
